    37  ZIP_EXTERN int
    38  zip_source_open(zip_source_t *src) {
    39      if (src->source_closed) {
    40          return -1;
    41      }
    42      if (src->write_state == ZIP_SOURCE_WRITE_REMOVED) {
    43          zip_error_set(&src->error, ZIP_ER_DELETED, 0);
    44          return -1;
    45      }
    46
    47      if (ZIP_SOURCE_IS_OPEN_READING(src)) {
    48          if ((zip_source_supports(src) & ZIP_SOURCE_MAKE_COMMAND_BITMASK(ZIP_SOURCE_SEEK)) == 0) {
    49              zip_error_set(&src->error, ZIP_ER_INUSE, 0);
    50              return -1;
    51          }
    52      }
    53      else {
    54          if (ZIP_SOURCE_IS_LAYERED(src)) {
    55              if (zip_source_open(src->src) < 0) {
    56                  zip_error_set_from_source(&src->error, src->src);
    57                  return -1;
    58              }
    59          }
    60
    61          if (_zip_source_call(src, NULL, 0, ZIP_SOURCE_OPEN) < 0) {
    62              if (ZIP_SOURCE_IS_LAYERED(src)) {
    63                  zip_source_close(src->src);
    64              }
    65              return -1;
    66          }
    67      }
    68
    69      src->eof = false;
    70      src->had_read_error = false;
    71      _zip_error_clear(&src->error);
    72      src->bytes_read = 0;
    73      src->open_count++;
    74
    75      return 0;
