   110
   111      case EXISTS_NOT:
   112          if ((flags & ZIP_CREATE) == 0) {
   113              zip_error_set(error, ZIP_ER_NOENT, 0);
   114              return NULL;
   115          }
   116          return _zip_allocate_new(src, flags, error);
   117
   118      default: {
   119          zip_t *za;
   120          if (flags & ZIP_EXCL) {
   121              zip_error_set(error, ZIP_ER_EXISTS, 0);
   122              return NULL;
   123          }
   124          if (zip_source_open(src) < 0) {
   125              zip_error_set_from_source(error, src);
   126              return NULL;
   127          }
   128
   129          if (flags & ZIP_TRUNCATE) {
   130              za = _zip_allocate_new(src, flags, error);
   131          }
   132          else {
   133              /* ZIP_CREATE gets ignored if file exists and not ZIP_EXCL, just like open() */
   134              za = _zip_open(src, flags, error);
   135          }
   136
   137          if (za == NULL) {
   138              zip_source_close(src);
   139              return NULL;
   140          }
   141          return za;
   142      }
   143      }
