   147  zip_t *
   148  _zip_open(zip_source_t *src, unsigned int flags, zip_error_t *error) {
   149      zip_t *za;
   150      zip_cdir_t *cdir;
   151      struct zip_stat st;
   152      zip_uint64_t len, idx;
   153
   154      zip_stat_init(&st);
   155      if (zip_source_stat(src, &st) < 0) {
   156          zip_error_set_from_source(error, src);
   157          return NULL;
   158      }
   159      if ((st.valid & ZIP_STAT_SIZE) == 0) {
   160          zip_error_set(error, ZIP_ER_SEEK, EOPNOTSUPP);
   161          return NULL;
   162      }
   163      len = st.size;
   164
   165
   166      if ((za = _zip_allocate_new(src, flags, error)) == NULL) {
   167          return NULL;
   168      }
   169
   170      /* treat empty files as empty archives */
   171      if (len == 0 && zip_source_accept_empty(src)) {
   172          return za;
   173      }
   174
   175      if ((cdir = _zip_find_central_dir(za, len)) == NULL) {
   176          _zip_error_copy(error, &za->error);
   177          /* keep src so discard does not get rid of it */
   178          zip_source_keep(src);
   179          zip_discard(za);
   180          return NULL;
   180          return NULL;
   181      }
   182
   183      za->entry = cdir->entry;
   184      za->nentry = cdir->nentry;
   185      za->nentry_alloc = cdir->nentry_alloc;
   186
   187      zip_check_torrentzip(za, cdir);
   188
   189      if (!ZIP_IS_TORRENTZIP(za)) {
   190          /* Torrentzip uses the archive comment to detect changes by tools that are not torrentzip aware. */
   191          za->comment_orig = cdir->comment;
   192      }
   193
   194      free(cdir);
   195
   196      _zip_hash_reserve_capacity(za->names, za->nentry, &za->error);
   197
   198      for (idx = 0; idx < za->nentry; idx++) {
   199          const zip_uint8_t *name = _zip_string_get(za->entry[idx].orig->filename, NULL, 0, error);
   200          if (name == NULL) {
   201              /* keep src so discard does not get rid of it */
   202              zip_source_keep(src);
   203              zip_discard(za);
   204              return NULL;
   205          }
   206
   207          if (_zip_hash_add(za->names, name, idx, ZIP_FL_UNCHANGED, &za->error) == false) {
   208              if (za->error.zip_err != ZIP_ER_EXISTS || (flags & ZIP_CHECKCONS)) {
   209                  _zip_error_copy(error, &za->error);
   210                  /* keep src so discard does not get rid of it */
   211                  zip_source_keep(src);
   212                  zip_discard(za);
   213                  return NULL;
   214              }
   215          }
   216      }
   217
   218      za->ch_flags = za->flags;
   219
   220      return za;
   221  }
