   225  _zip_set_open_error(int *zep, const zip_error_t *err, int ze) {
   226      if (err) {
   227          ze = zip_error_code_zip(err);
   228          switch (zip_error_system_type(err)) {
   229              case ZIP_ET_SYS:
   230              case ZIP_ET_LIBZIP:
   231                  errno = zip_error_code_system(err);
   232                  break;
   233
   234              default:
   235                  break;
   236          }
   237      }
   238
   239      if (zep)
   240          *zep = ze;
   241  }
