   244  /* _zip_readcdir:
   245     tries to find a valid end-of-central-directory at the beginning of
   246     buf, and then the corresponding central directory entries.
   247     Returns a struct zip_cdir which contains the central directory
   248     entries, or NULL if unsuccessful. */
   249
   250  static zip_cdir_t *
   251  _zip_read_cdir(zip_t *za, zip_buffer_t *buffer, zip_uint64_t buf_offset, zip_error_t *error) {
   252      zip_cdir_t *cd;
   253      zip_uint16_t comment_len;
   254      zip_uint64_t i, left;
   255      zip_uint64_t eocd_offset = _zip_buffer_offset(buffer);
   256      zip_buffer_t *cd_buffer;
   257
   258      if (_zip_buffer_left(buffer) < EOCDLEN) {
   259          /* not enough bytes left for comment */
   260          zip_error_set(error, ZIP_ER_NOZIP, 0);
   261          return NULL;
   262      }
   263
   264      /* check for end-of-central-dir magic */
   265      if (memcmp(_zip_buffer_get(buffer, 4), EOCD_MAGIC, 4) != 0) {
   266          zip_error_set(error, ZIP_ER_NOZIP, 0);
   267          return NULL;
   268      }
   269
   270      if (eocd_offset >= EOCD64LOCLEN && memcmp(_zip_buffer_data(buffer) + eocd_offset - EOCD64LOCLEN, EOCD64LOC_MAGIC, 4) == 0) {
   271          _zip_buffer_set_offset(buffer, eocd_offset - EOCD64LOCLEN);
   272          cd = _zip_read_eocd64(za->src, buffer, buf_offset, za->flags, error);
   273      }
   274      else {
   275          _zip_buffer_set_offset(buffer, eocd_offset);
   276          cd = _zip_read_eocd(buffer, buf_offset, za->flags, error);
   277      }
   278
   279      if (cd == NULL)
   280          return NULL;
   281
   282      _zip_buffer_set_offset(buffer, eocd_offset + 20);
   283      comment_len = _zip_buffer_get_16(buffer);
   284
   285      if (cd->offset + cd->size > buf_offset + eocd_offset) {
   286          /* cdir spans past EOCD record */
   287          zip_error_set(error, ZIP_ER_INCONS, ZIP_ER_DETAIL_CDIR_OVERLAPS_EOCD);
   288          _zip_cdir_free(cd);
   289          return NULL;
   290      }
   291
   292      if (comment_len || (za->open_flags & ZIP_CHECKCONS)) {
   293          zip_uint64_t tail_len;
   294
   295          _zip_buffer_set_offset(buffer, eocd_offset + EOCDLEN);
   296          tail_len = _zip_buffer_left(buffer);
   297
   298          if (tail_len < comment_len || ((za->open_flags & ZIP_CHECKCONS) && tail_len != comment_len)) {
   299              zip_error_set(error, ZIP_ER_INCONS, ZIP_ER_DETAIL_COMMENT_LENGTH_INVALID);
   300              _zip_cdir_free(cd);
   301              return NULL;
   302          }
   303
   304          if (comment_len) {
   305              if ((cd->comment = _zip_string_new(_zip_buffer_get(buffer, comment_len), comment_len, ZIP_FL_ENC_GUESS, error)) == NULL) {
   306                  _zip_cdir_free(cd);
   307                  return NULL;
   308              }
   309          }
   310      }
   311
   312      if (cd->offset >= buf_offset) {
   313          zip_uint8_t *data;
   314          /* if buffer already read in, use it */
   315          _zip_buffer_set_offset(buffer, cd->offset - buf_offset);
   316
   317          if ((data = _zip_buffer_get(buffer, cd->size)) == NULL) {
   318              zip_error_set(error, ZIP_ER_INCONS, ZIP_ER_DETAIL_CDIR_LENGTH_INVALID);
   319              _zip_cdir_free(cd);
   320              return NULL;
   321          }
   322          if ((cd_buffer = _zip_buffer_new(data, cd->size)) == NULL) {
   323              zip_error_set(error, ZIP_ER_MEMORY, 0);
   324              _zip_cdir_free(cd);
   325              return NULL;
   326          }
   327      }
   328      else {
   329          cd_buffer = NULL;
   330
   331          if (zip_source_seek(za->src, (zip_int64_t)cd->offset, SEEK_SET) < 0) {
   332              zip_error_set_from_source(error, za->src);
   333              _zip_cdir_free(cd);
   334              return NULL;
   335          }
   336
   337          /* possible consistency check: cd->offset = len-(cd->size+cd->comment_len+EOCDLEN) ? */
   338          if (zip_source_tell(za->src) != (zip_int64_t)cd->offset) {
   339              zip_error_set(error, ZIP_ER_NOZIP, 0);
   340              _zip_cdir_free(cd);
   341              return NULL;
   342          }
   343      }
   344
   345      left = (zip_uint64_t)cd->size;
   346      i = 0;
   347      while (left > 0) {
   348          bool grown = false;
   349          zip_int64_t entry_size;
   350
   351          if (i == cd->nentry) {
   352              /* InfoZIP has a hack to avoid using Zip64: it stores nentries % 0x10000 */
   353              /* This hack isn't applicable if we're using Zip64, or if there is no central directory entry following. */
   354
   355              if (cd->is_zip64 || left < CDENTRYSIZE) {
   356                  break;
   357              }
